 21→// WithSession adds a session ID to the context.
 22→// If the context already has a session ID, it becomes the parent session ID.
 23→func WithSession(ctx context.Context, sessionID string) context.Context {
 24→	// If there's an existing session, it becomes the parent
 25→	existing := SessionIDFromContext(ctx)
 26→	if existing != "" && existing != sessionID {
 27→		ctx = context.WithValue(ctx, parentSessionIDKey, existing)
 28→	}
 29→	return context.WithValue(ctx, sessionIDKey, sessionID)
 30→}
 31→
 32→// WithParentSession explicitly sets the parent session ID.
 33→// Use this when you need to set the parent explicitly rather than
 34→// having it inferred from an existing session.
 35→func WithParentSession(ctx context.Context, parentSessionID string) context.Context {
 36→	return context.WithValue(ctx, parentSessionIDKey, parentSessionID)
 37→}
