 39→// WithToolCall adds a tool call ID to the context.
 40→func WithToolCall(ctx context.Context, toolCallID string) context.Context {
 41→	return context.WithValue(ctx, toolCallIDKey, toolCallID)
 42→}
 43→
 44→// WithComponent adds a component name to the context.
 45→// Component names help identify the subsystem generating logs (e.g., "hooks", "strategy", "session").
 46→func WithComponent(ctx context.Context, component string) context.Context {
 47→	return context.WithValue(ctx, componentKey, component)
 48→}
