 51→// Agent names identify the AI agent generating activity (e.g., "claude-code", "cursor", "aider").
 52→func WithAgent(ctx context.Context, agentName types.AgentName) context.Context {
 53→	return context.WithValue(ctx, agentKey, string(agentName))
